  async stopAgent(id: ID, actor: string): Promise<AgentBinding> { return this.locked(s => { const a=required(s.agents.find(x=>x.id===id), `agent ${id} not found`); const n={...a,status:"stopped" as const,revision:a.revision+1,updatedAt:iso()}; s.agents[s.agents.indexOf(a)]=n; this.event(s,"agent.stopped",id,actor); return clone(n); }); }
  async createJob(request: CreateJobRequest, actor: string): Promise<Job> { return this.locked(s => { if(!request.request.prompt.trim()||!request.idempotencyKey.trim()) fail("invalid_request","prompt and idempotencyKey are required"); const old=s.jobs.find(j=>j.idempotencyKey===request.idempotencyKey); if(old)return clone(old); const t=iso(); const j:Job={id:`job:${crypto.randomUUID()}` as ID,request:clone(request.request),policyProfile:request.policyProfile,state:"queued",attempt:0,idempotencyKey:request.idempotencyKey,createdAt:t,updatedAt:t}; s.jobs.push(j); this.event(s,"job.created",j.id,actor); return clone(j); }); }
  async listAgents(): Promise<readonly AgentBinding[]> { return this.locked(s => clone(s.agents)); }
  async listJobs(): Promise<readonly Job[]> { return this.locked(s => clone(s.jobs)); }
  async getJob(id: ID): Promise<Job> { return this.locked(s => { const j=required(s.jobs.find(x=>x.id===id), `job ${id} not found`); return clone(j); }); }
  async cancelJob(id: ID, actor: string): Promise<Job> { return this.locked(s => this.transition(s,id,"cancelled",actor,"job.cancelled")); }
  async retryJob(id: ID, actor: string): Promise<Job> { return this.locked(s => { const j=required(s.jobs.find(x=>x.id===id), `job ${id} not found`); if(j.state!=="failed"&&j.state!=="cancelled")fail("conflict",`job ${id} is not retryable`); const n={...j,state:"queued" as const,attempt:j.attempt+1,updatedAt:iso()}; s.jobs[s.jobs.indexOf(j)]=n; this.event(s,"job.retried",id,actor); return clone(n); }); }
  private transition(s:State,id:ID,state:"cancelled",actor:string,type:ControlPlaneEvent["type"]):Job { const j=required(s.jobs.find(x=>x.id===id), `job ${id} not found`); if(["succeeded","failed","cancelled"].includes(j.state))fail("already_terminal",`job ${id} is terminal`); const n={...j,state,updatedAt:iso()}; s.jobs[s.jobs.indexOf(j)]=n; this.event(s,type,id,actor); return clone(n); }
  async readEvents(afterSequence=0,limit=100):Promise<{events:ControlPlaneEvent[];nextSequence:number}>{ return this.locked(s=>{if(!Number.isSafeInteger(afterSequence)||afterSequence<0||!Number.isSafeInteger(limit)||limit<1)fail("invalid_request","invalid event cursor or limit");const e=s.events.filter(x=>x.sequence>afterSequence).slice(0,limit);return {events:clone(e),nextSequence:e.at(-1)?.sequence??afterSequence};}); }
  async claimJob(ownerId=this.ownerId, leaseMs=this.leaseMs):Promise<JobLease|undefined>{ return this.locked(s=>{const now=Date.now();s.leases=s.leases.filter(l=>Date.parse(l.expiresAt)>now);const j=s.jobs.find(x=>x.state==="queued"&&!s.leases.some(l=>l.jobId===x.id));if(!j)return undefined;const lease:JobLease={jobId:j.id,attempt:j.attempt+1,leaseToken:crypto.randomUUID(),ownerId,expiresAt:new Date(now+leaseMs).toISOString()};s.leases.push(lease);s.jobs[s.jobs.indexOf(j)]={...j,state:"leased",attempt:lease.attempt,updatedAt:iso()};return clone(lease);}); }
  async renewLease(lease:JobLease, leaseMs=this.leaseMs):Promise<JobLease>{return this.locked(s=>{const l=required(s.leases.find(x=>x.jobId===lease.jobId&&x.leaseToken===lease.leaseToken&&x.ownerId===lease.ownerId&&lease.ownerId===this.ownerId), "lease lost");if(Date.parse(l.expiresAt)<=Date.now())fail("conflict","lease lost");const n={...l,expiresAt:new Date(Date.now()+leaseMs).toISOString()};s.leases[s.leases.indexOf(l)]=n;return clone(n);});}
  async completeLease(lease:JobLease, state:"succeeded"|"failed"):Promise<Job>{return this.locked(s=>{const l=s.leases.find(x=>x.jobId===lease.jobId&&x.leaseToken===lease.leaseToken&&x.ownerId===lease.ownerId&&lease.ownerId===this.ownerId);if(!l||Date.parse(l.expiresAt)<=Date.now())fail("conflict","lease lost");const j=required(s.jobs.find(x=>x.id===lease.jobId), `job ${lease.jobId} not found`);const n={...j,state,updatedAt:iso()};s.jobs[s.jobs.indexOf(j)]=n;s.leases=s.leases.filter(x=>x!==l);return clone(n);});}
  async recoverExpiredLeases():Promise<number>{return this.locked(s=>{const now=Date.now();let count=0;for(const l of s.leases.filter(x=>Date.parse(x.expiresAt)<=now)){const j=s.jobs.find(x=>x.id===l.jobId);if(j&&j.state==="leased"){s.jobs[s.jobs.indexOf(j)]={...j,state:"queued",updatedAt:iso()};count++;}s.leases=s.leases.filter(x=>x!==l);}return count;});}
}
